text:
リスト内包表記がない Go で、for + append のかたまりが何度も登場するなら、関数に切り出すのが Go 流です。Python では内包表記を 1 行で使い回しましたが、Go では「スライスを受け取り、新しいスライスを返す関数」を定義して名前を付けます。呼び出す側は 1 行になり、内包表記と同じ読みやすさに戻ります。処理に名前が付くぶん、意図はむしろ伝わりやすくなります。🟡 変換処理を関数にまとめる発想を理屈で理解しましょう。

Python ではこう書いた:

```python
doubled = [x * 2 for x in nums]
```

Go ではこう書く:

```go
func double(nums []int) []int {
	result := []int{}
	for _, x := range nums {
		result = append(result, x*2)
	}
	return result
}

// 呼び出す側は 1 行に戻る
doubled := double(nums)
```

sample:
// lesson14 ch03: 関数に切り出すのが Go 流
package main

import "fmt"

// squares は各要素を 2 乗した新しいスライスを返す
func squares(nums []int) []int {
	result := []int{}
	for _, x := range nums {
		result = append(result, x*x)
	}
	return result
}

// bigOnly は 10 以上の値だけを集めた新しいスライスを返す
func bigOnly(nums []int) []int {
	result := []int{}
	for _, x := range nums {
		if x >= 10 {
			result = append(result, x)
		}
	}
	return result
}

func main() {
	nums := []int{3, 12, 5, 20}
	// 呼び出す側は内包表記と同じ 1 行で読めます
	fmt.Println(squares(nums)) // [9 144 25 400]
	fmt.Println(bigOnly(nums)) // [12 20]
}

